#!/bin/sh
#
# Build the avcpp documentation site.
#
# Produces, under the output directory:
#
#   index.html            version chooser (regenerated by docs/site-index.sh)
#   404.html              redirect map for the pre-3.1 flat URLs
#   <version>/            English reference and guides
#   <version>/ru/         Russian guides
#   latest/               copy of the newest build
#
# The version comes from VERSION.txt. Run this from anywhere; paths are
# resolved relative to the script location.
#
# Usage: docs/build.sh [--out DIR] [--serve] [--port N] [--no-latest]

set -eu

ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
CALLER_PWD=$PWD
VERSION=$(tr -d '[:space:]' < "$ROOT/VERSION.txt")
# Archives are cut per minor: 3.1.0 and 3.1.1 both refresh the 3.1 directory.
DOC_VERSION=${VERSION%.*}
DOXYGEN=${DOXYGEN:-doxygen}

OUT="$ROOT/build/docs/site"
SERVE=0
PORT=8000
MAKE_LATEST=1

usage()
{
    cat <<'EOF'
Usage: docs/build.sh [options]

  --out DIR    output directory (default: build/docs/site)
  --serve      serve the result on http://localhost:8000 after building
  --port N     port for --serve (default: 8000)
  --no-latest  do not refresh the "latest" copy
  -h, --help   show this help
EOF
}

while [ $# -gt 0 ]; do
    case "$1" in
        --out)
            [ $# -ge 2 ] || { echo "docs/build.sh: --out needs a value" >&2; exit 2; }
            OUT=$2
            shift 2
            ;;
        --serve)
            SERVE=1
            shift
            ;;
        --port)
            [ $# -ge 2 ] || { echo "docs/build.sh: --port needs a value" >&2; exit 2; }
            PORT=$2
            shift 2
            ;;
        --no-latest)
            MAKE_LATEST=0
            shift
            ;;
        -h|--help)
            usage
            exit 0
            ;;
        *)
            echo "docs/build.sh: unknown option: $1" >&2
            usage >&2
            exit 2
            ;;
    esac
done

case "$OUT" in
    /*) ;;
    *) OUT="$CALLER_PWD/$OUT" ;;
esac

if ! command -v "$DOXYGEN" >/dev/null 2>&1; then
    echo "docs/build.sh: doxygen not found: $DOXYGEN" >&2
    exit 1
fi

mkdir -p "$OUT"
EN_DIR="$OUT/$DOC_VERSION"
RU_DIR="$OUT/$DOC_VERSION/ru"

# doxygen resolves relative paths against the current directory, so every run
# happens from the repository root and the output directory is absolute.
build_language()
{
    include=$1
    out_dir=$2
    config=$(mktemp)

    {
        echo "@INCLUDE = $include"
        echo "OUTPUT_DIRECTORY = $out_dir"
        echo "HTML_OUTPUT = ."
    } > "$config"

    mkdir -p "$out_dir"
    ( cd "$ROOT" && AVCPP_VERSION="$VERSION" "$DOXYGEN" "$config" )
    rm -f "$config"
}

echo "==> English reference and guides -> $EN_DIR"
build_language "$ROOT/Doxyfile" "$EN_DIR"

echo "==> Russian guides -> $RU_DIR"
build_language "$ROOT/docs/ru.doxyfile" "$RU_DIR"

if [ "$MAKE_LATEST" = 1 ]; then
    echo "==> latest/"
    rm -rf "$OUT/latest"
    cp -a "$EN_DIR" "$OUT/latest"
fi

echo "==> index.html and 404.html"
"$ROOT/docs/site-index.sh" "$OUT"

echo
echo "Documentation built in $OUT"
echo "Latest English: $OUT/latest/index.html"
echo "Latest Russian: $OUT/latest/ru/index.html"

if [ "$SERVE" = 1 ]; then
    echo "Serving on http://localhost:$PORT/ (Ctrl-C to stop)"
    cd "$OUT" && exec python3 -m http.server "$PORT"
fi
